<section class="pm-section"><h2>Eigenständige Aufgabe erstellen</h2><p>Diese Aufgabe gehört zu keinem Projekt. Beginn und Fälligkeit sind absolute Kalenderdaten. Bei einer Wiederholung wird nach dem Erledigen automatisch die nächste Aufgabe angelegt.</p><form method="post" class="pm-form"><input type="hidden" name="csrf_token" value="<?=pmh($csrf)?>"><input type="hidden" name="action" value="create_standalone_task"><label>Titel<input name="title" required placeholder="z. B. Weihnachtstombola vorbereiten"></label><label>Beschreibung<textarea name="description" rows="2"></textarea></label><label>Link zu Vorlage / Ressource<input type="url" name="resource_url" placeholder="https://…"></label><div class="pm-form-grid"><label>Beginn<input type="date" name="start_date" required></label><label>Fällig am<input type="date" name="due_date" required></label></div><label class="pm-check-row"><input type="checkbox" id="pm-repeat-enable"><span>Aufgabe wiederholen</span></label><div class="pm-form-grid" id="pm-repeat-fields" hidden><label>Alle<input type="number" name="recurrence_every" min="1" max="999" value="1" disabled></label><label>Zeiteinheit<select name="recurrence_unit" id="pm-repeat-unit" disabled><option value="week">Wochen</option><option value="month">Monate</option><option value="year">Jahre</option></select></label></div><script>(function(){const checkbox=document.getElementById("pm-repeat-enable");const fields=document.getElementById("pm-repeat-fields");if(!checkbox||!fields)return;function syncRepeatFields(){fields.hidden=!checkbox.checked;fields.querySelectorAll("input,select").forEach(function(control){control.disabled=!checkbox.checked;});}checkbox.addEventListener("change",syncRepeatFields);syncRepeatFields();})();</script><button class="pm-button primary" type="submit">Einzelaufgabe erstellen</button></form></section>
<section class="pm-section"><h2>Eigenständige Aufgaben</h2><?php $q=$conn->query("SELECT s.*,u.full_name assignee FROM standalone_tasks s LEFT JOIN users u ON u.id=s.assigned_user_id ORDER BY CASE s.status WHEN 'open' THEN 0 WHEN 'in_progress' THEN 1 ELSE 2 END,s.due_date DESC,s.id DESC");$standaloneList=$q->fetchAll(PDO::FETCH_ASSOC);if(!$standaloneList):?><p class="pm-empty-card">Noch keine eigenständigen Aufgaben angelegt.</p><?php else:foreach($standaloneList as $st):?><details class="pm-template-task-editor" id="standalone-task-<?=$st['id']?>"><summary><?=pmh($st['title'])?> <span class="pm-offset"><?=pmd($st['start_date'])?> – <?=pmd($st['due_date'])?> · <?=$st['status']==='done'?'Erledigt':($st['status']==='in_progress'?'In Bearbeitung':'Offen')?><?=!empty($st['recurrence_every'])?' · alle '.(int)$st['recurrence_every'].' '.(['week'=>'Wochen','month'=>'Monate','year'=>'Jahre'][$st['recurrence_unit']]??''):''?></span></summary><form method="post" class="pm-form"><input type="hidden" name="csrf_token" value="<?=pmh($csrf)?>"><input type="hidden" name="action" value="update_standalone_task"><input type="hidden" name="standalone_task_id" value="<?=$st['id']?>"><label>Titel<input name="title" required value="<?=pmh($st['title'])?>"></label><label>Beschreibung<textarea name="description" rows="2"><?=pmh($st['description'])?></textarea></label><label>Link zu Vorlage / Ressource<input type="url" name="resource_url" value="<?=pmh($st['resource_url'])?>"></label><div class="pm-form-grid"><label>Beginn<input type="date" name="start_date" required value="<?=pmh($st['start_date'])?>"></label><label>Fällig am<input type="date" name="due_date" required value="<?=pmh($st['due_date'])?>"></label><label>Status<select name="status"><option value="open" <?=$st['status']==='open'?'selected':''?>>Offen</option><option value="in_progress" <?=$st['status']==='in_progress'?'selected':''?>>In Bearbeitung</option><option value="done" <?=$st['status']==='done'?'selected':''?>>Erledigt</option></select></label><label>Wiederholung alle<input type="number" name="recurrence_every" min="1" max="999" value="<?=pmh($st['recurrence_every'])?>" placeholder="leer = keine Wiederholung"></label><label>Zeiteinheit<select name="recurrence_unit"><option value="week" <?=$st['recurrence_unit']==='week'?'selected':''?>>Wochen</option><option value="month" <?=$st['recurrence_unit']==='month'?'selected':''?>>Monate</option><option value="year" <?=$st['recurrence_unit']==='year'?'selected':''?>>Jahre</option></select></label></div><button class="pm-button primary" type="submit">Änderungen speichern</button></form><form method="post" onsubmit="return confirm('Diese Einzelaufgabe wirklich löschen?')"><input type="hidden" name="csrf_token" value="<?=pmh($csrf)?>"><input type="hidden" name="action" value="delete_standalone_task"><input type="hidden" name="standalone_task_id" value="<?=$st['id']?>"><button class="pm-button small secondary" type="submit">Aufgabe löschen</button></form></details><?php endforeach;endif;?></section>
