<p class="pm-back"><a href="projects.php?view=templates">← Zurück zu den Vorlagen</a></p><section class="pm-section"><h2>Projektvorlage bearbeiten</h2><form method="post" class="pm-form"><input type="hidden" name="csrf_token" value="<?=pmh($csrf)?>"><input type="hidden" name="action" value="save_project_template"><input type="hidden" name="template_id" value="<?=$pid?>"><label>Name<input name="name" required value="<?=pmh($editTemplate['name'])?>"></label><label>Typ<select name="project_type"><option value="event" <?=$editTemplate['project_type']==='event'?'selected':''?>>Veranstaltung</option><option value="project" <?=$editTemplate['project_type']==='project'?'selected':''?>>Allgemeines Projekt</option></select></label><label>Beschreibung<textarea name="description" rows="3"><?=pmh($editTemplate['description'])?></textarea></label><label>Projektfarbe<input type="color" name="color" value="<?=pmh(pmcolor($editTemplate['color']??null))?>"></label><button class="pm-button primary" type="submit">Vorlage speichern</button></form></section>
<section class="pm-section"><div class="pm-section-heading"><div><h2>Aufgaben dieser Vorlage</h2><p>Diese Aufgaben gehören nur zu „<?=pmh($editTemplate['name'])?>“. Links und Texte werden beim Erstellen eines Projekts mitkopiert.</p></div></div><?php foreach($editTemplateTasks as $tt):?><details class="pm-template-task-editor"><summary><?=pmh($tt['title'])?> <span class="pm-offset">Beginn <?= $tt['start_offset_days']===null?'—':(int)$tt['start_offset_days'].' T.' ?> · Fällig <?= $tt['due_offset_days']===null?'—':(int)$tt['due_offset_days'].' T.' ?></span></summary><form method="post" class="pm-form"><input type="hidden" name="csrf_token" value="<?=pmh($csrf)?>"><input type="hidden" name="action" value="update_template_task"><input type="hidden" name="template_id" value="<?=$pid?>"><input type="hidden" name="template_task_id" value="<?=$tt['id']?>"><label>Titel<input name="title" required value="<?=pmh($tt['title'])?>"></label><label>Beschreibung<textarea name="task_description" rows="2"><?=pmh($tt['description'])?></textarea></label><label>Link zu Vorlage / Ressource<input type="url" name="resource_url" value="<?=pmh($tt['resource_url'])?>" placeholder="https://…"></label><p class="pm-offset-help">Negative Werte liegen vor dem Termin, positive danach. Über die Wochen-Schaltflächen kannst du den Zeitpunkt schnell verschieben.</p><div class="pm-form-grid"><label>Arbeitsbeginn<input type="number" name="start_offset_days" value="<?=pmh($tt['start_offset_days'])?>" placeholder="-56"></label><label>Fälligkeit<input type="number" name="due_offset_days" value="<?=pmh($tt['due_offset_days'])?>" placeholder="-14"></label><label>Sortierung<input type="number" name="sort_order" value="<?=pmh($tt['sort_order'])?>"></label></div><label class="pm-check-row"><input type="checkbox" name="default_selected" value="1" <?=$tt['default_selected']?'checked':''?>> <span>Beim Erstellen eines Projekts standardmäßig ausgewählt</span></label><button class="pm-button primary" type="submit">Aufgabe speichern</button></form><form method="post" onsubmit="return confirm('Diese Aufgabe aus der Projektvorlage entfernen? Bereits angelegte Projekte bleiben unverändert.')"><input type="hidden" name="csrf_token" value="<?=pmh($csrf)?>"><input type="hidden" name="action" value="remove_template_task"><input type="hidden" name="template_id" value="<?=$pid?>"><input type="hidden" name="template_task_id" value="<?=$tt['id']?>"><button class="pm-button small secondary" type="submit">Aus Vorlage entfernen</button></form></details><?php endforeach;if(!$editTemplateTasks):?><p class="pm-empty-card">Diese Vorlage enthält noch keine Aufgaben.</p><?php endif;?></section>
<section class="pm-section"><h2>Eigene Aufgabe hinzufügen</h2><form method="post" class="pm-form"><input type="hidden" name="csrf_token" value="<?=pmh($csrf)?>"><input type="hidden" name="action" value="add_template_task"><input type="hidden" name="template_id" value="<?=$pid?>"><label>Titel<input name="title" required placeholder="z. B. Sponsorenlauf-Poster drucken"></label><label>Beschreibung<textarea name="task_description" rows="2"></textarea></label><label>Link zu Vorlage / Ressource<input type="url" name="resource_url" placeholder="https://…"></label><p class="pm-offset-help">Negative Werte liegen vor dem Termin, positive danach. Über die Wochen-Schaltflächen kannst du den Zeitpunkt schnell verschieben.</p><div class="pm-form-grid"><label>Arbeitsbeginn<input type="number" name="start_offset_days" placeholder="-56"></label><label>Fälligkeit<input type="number" name="due_offset_days" placeholder="-14"></label><label>Sortierung<input type="number" name="sort_order" value="0"></label></div><label class="pm-check-row"><input type="checkbox" name="default_selected" value="1" checked><span>Beim Erstellen eines Projekts standardmäßig ausgewählt</span></label><button class="pm-button primary" type="submit">Aufgabe hinzufügen</button></form></section>
<section class="pm-section"><h2>Allgemeine Aufgabenvorlage übernehmen</h2><p>Es wird eine eigenständige Kopie in dieser Projektvorlage angelegt. Anschließend kannst du Titel, Fristen und Link hier unabhängig bearbeiten.</p><?php if($taskTemplates):?><form method="post" class="pm-form"><input type="hidden" name="csrf_token" value="<?=pmh($csrf)?>"><input type="hidden" name="action" value="add_library_task_to_template"><input type="hidden" name="template_id" value="<?=$pid?>"><label>Aufgabenvorlage<select name="source_task_template_id" required><?php foreach($taskTemplates as $tt):?><option value="<?=$tt['id']?>"><?=pmh($tt['title'])?></option><?php endforeach;?></select></label><button class="pm-button" type="submit">Kopie in diese Projektvorlage übernehmen</button></form><?php else:?><p class="pm-muted">Es gibt noch keine allgemeinen Aufgabenvorlagen.</p><?php endif;?></section>
<?php endif;?></main></div>
<script>
const pmTemplateSelect=document.getElementById('template-select');
<?php if($view==='new'):?>
const pmType=document.getElementById('project-type'),pmList=document.getElementById('template-task-list');
function pmToggleType(){const ev=pmType.value==='event';document.querySelectorAll('.event-field').forEach(x=>x.style.display=ev?'':'none');document.querySelectorAll('.project-field').forEach(x=>x.style.display=ev?'none':'');document.getElementById('event-date').required=ev;document.getElementById('start-date').required=!ev;}
function pmOffset(offset){const el=pmType.value==='event'?document.getElementById('event-date'):document.getElementById('start-date');if(!el.value||offset===null)return 'Datum offen';const d=new Date(el.value+'T12:00:00');d.setDate(d.getDate()+Number(offset));return d.toLocaleDateString('de-DE');}
async function pmLoadTasks(){const selectedBefore=new Set(Array.from(pmList.querySelectorAll('input[name="selected_tasks[]"]:checked')).map(x=>x.value));const hadChoices=pmList.querySelectorAll('input[name="selected_tasks[]"]').length>0;const id=Number(pmTemplateSelect.value);if(!id){pmList.innerHTML='<p class="pm-muted">Leeres Projekt: Aufgaben können nach dem Anlegen ergänzt werden.</p>';return;}const opt=pmTemplateSelect.selectedOptions[0];pmType.value=opt.dataset.type||'event';pmToggleType();const r=await fetch('projects.php?template_tasks='+id,{headers:{Accept:'application/json'}});if(!r.ok){pmList.textContent='Aufgaben konnten nicht geladen werden.';return;}const data=await r.json();pmList.innerHTML='';if(!data.tasks.length){pmList.innerHTML='<p class="pm-muted">Diese Vorlage enthält noch keine Aufgaben.</p>';return;}data.tasks.forEach(t=>{const label=document.createElement('label');label.className='pm-check-row';const cb=document.createElement('input');cb.type='checkbox';cb.name='selected_tasks[]';cb.value=t.id;cb.checked=hadChoices?selectedBefore.has(String(t.id)):!!Number(t.default_selected);const span=document.createElement('span');span.textContent=t.title;const small=document.createElement('small');small.textContent='Beginn: '+pmOffset(t.start_offset_days)+' · Fällig: '+pmOffset(t.due_offset_days);span.appendChild(small);if(t.resource_url){const link=document.createElement('a');link.href=t.resource_url;link.target='_blank';link.rel='noopener noreferrer';link.textContent='Ressource öffnen';link.addEventListener('click',e=>e.stopPropagation());span.appendChild(link);}label.append(cb,span);pmList.appendChild(label);});}
pmTemplateSelect.addEventListener('change',pmLoadTasks);pmType.addEventListener('change',()=>{pmToggleType();pmLoadTasks();});document.getElementById('event-date').addEventListener('change',pmLoadTasks);document.getElementById('start-date').addEventListener('change',pmLoadTasks);pmToggleType();
<?php endif;?>
function pmOffsetDescription(value){
 const n=Number(value);
 if(value===''||!Number.isFinite(n))return 'Kein relativer Zeitpunkt festgelegt';
 if(n===0)return 'Am Termin';
 const abs=Math.abs(n),weeks=Math.floor(abs/7),days=abs%7,side=n<0?'vorher':'nachher';
 let amount=weeks>0?(weeks+' '+(weeks===1?'Woche':'Wochen')):'';
 if(days>0)amount+=(amount?' und ':'')+days+' '+(days===1?'Tag':'Tage');
 if(!amount)amount=abs+' '+(abs===1?'Tag':'Tage');
 return amount+' '+side;
}
function pmInstallOffsetControls(){
 document.querySelectorAll('input[name="start_offset_days"],input[name="due_offset_days"]').forEach(input=>{
  if(input.dataset.offsetControls==='1')return;
  input.dataset.offsetControls='1';
  const label=input.parentElement;
  const wrap=document.createElement('div');wrap.className='pm-offset-control';
  label.insertBefore(wrap,input);
  const description=document.createElement('span');description.className='pm-offset-description';description.setAttribute('aria-live','polite');
  wrap.appendChild(description);
  const buttons=document.createElement('div');buttons.className='pm-offset-buttons';
  const makeButton=(text,title,delta)=>{
   const b=document.createElement('button');b.type='button';b.className='pm-button small secondary';b.textContent=text;b.title=title;
   b.addEventListener('click',()=>{const current=input.value===''?0:Number(input.value);input.value=String(current+delta);input.dispatchEvent(new Event('input',{bubbles:true}));input.dispatchEvent(new Event('change',{bubbles:true}));});
   buttons.appendChild(b);
  };
  makeButton('− 1 Woche','Zeitpunkt um sieben Tage früher legen',-7);
  makeButton('− 1 Tag','Zeitpunkt um einen Tag früher legen',-1);
  makeButton('+ 1 Tag','Zeitpunkt um einen Tag später legen',1);
  makeButton('+ 1 Woche','Zeitpunkt um sieben Tage später legen',7);
  wrap.appendChild(buttons);
  const inputArea=document.createElement('div');inputArea.className='pm-offset-input-area';
  inputArea.appendChild(input);
  const note=document.createElement('small');note.className='pm-offset-live';note.textContent='Tage relativ';inputArea.appendChild(note);
  wrap.appendChild(inputArea);
  const update=()=>{description.textContent=pmOffsetDescription(input.value);};
  input.addEventListener('input',update);input.addEventListener('change',update);update();
 });
}
pmInstallOffsetControls();
document.querySelectorAll('.pm-task-tile[data-task-url]').forEach(card=>{const go=()=>window.location.href=card.dataset.taskUrl;card.addEventListener('click',e=>{if(e.target.closest('a,button,form,input,textarea,select,label'))return;go();});card.addEventListener('keydown',e=>{if((e.key==='Enter'||e.key===' ')&&!e.target.closest('a,button,form,input,textarea,select,label')){e.preventDefault();go();}});});
document.querySelectorAll('[data-toggle]').forEach(b=>b.addEventListener('click',()=>{const d=document.getElementById(b.dataset.toggle);if(d){d.open=!d.open;d.scrollIntoView({behavior:'smooth',block:'nearest'});}}));
</script></body></html>
